SELECT AVG(CAST((taxpayer_8.average_medicare_allowed_amt - taxpayer_8.average_medicare_payment_amt) AS double precision)) AS avg_calculation_9940518082838207_ok,   AVG(CAST(taxpayer_8.average_medicare_allowed_amt AS double precision)) AS avg_average_medicare_allowed_amt_ok,   AVG(CAST(taxpayer_8.average_medicare_payment_amt AS double precision)) AS avg_average_medicare_payment_amt_ok,   AVG(CAST(taxpayer_8.average_submitted_chrg_amt AS double precision)) AS avg_average_submitted_chrg_amt_ok,   taxpayer_8.hcpcs_description AS hcpcs_description FROM taxpayer_8 WHERE ((taxpayer_8.nppes_provider_first_name = 'JOHN') AND (taxpayer_8.nppes_provider_last_org_name = 'HOLDER') AND (taxpayer_8.nppes_provider_state = 'WA')) GROUP BY taxpayer_8.hcpcs_description;
